function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // liver
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // liver damage
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 20, H/2 + Math.cos(t) * 20, 10, 0, 2 * Math.PI);
  ctx.fill();

  // alcohol molecules
  ctx.fillStyle = 'blue';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.sin(t + i) * 100, H/2 + Math.cos(t + i) * 100, 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 80, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 120, H/2 - 20);
  ctx.stroke();

  ctx.restore();
}
